mapper.select:
select productioncode from sdsshop.u_p_production
 where shop_code = #{shopCode} and productioncode = #{productionCode}
 for update


 where shop_code = #{shopCode}
and productioncode = #{productionCode}
and sourcetype = #{sourceType}
and productcode = #{productCode}


    and status in ('待生产', '待领料', '生产中')
    and status = #{status}


 order by createtime desc, productioncode desc

mapper.insert:
insert into sdsshop.u_p_production(
    shop_code, productioncode, sourcetype, sourceordercodes, orderallocation,
    productcode, productname, planyqty, actualyqty, plandate, status,
    materialcost, processingcost, freightcost, othercost, totalcost, unitcost,
    createuser, createtime, remark
) values (
    #{shopCode}, #{productionCode}, #{sourceType}, #{sourceOrderCodes}, #{orderAllocation},
    #{productCode}, #{productName}, #{planYQty}, 0, #{planDate}, '待生产',
    0, 0, 0, 0, 0, 0, #{createUser}, sysdate(), #{remark}
)

mapper.update:
update sdsshop.u_p_production
   set status = #{status}, updateuser = #{updateUser}, updatetime = sysdate()
 where shop_code = #{shopCode} and productioncode = #{productionCode}

mapper.delete:
delete from sdsshop.u_p_production
 where shop_code = #{shopCode} and productioncode = #{productionCode}
   and status = '待生产'
